const uiIcon=name=>`<svg class="ui-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${name==='check'?'<path d="m5 12 4 4L19 6"/>':'<path d="M7 18h11a4 4 0 0 0 .5-8 6.5 6.5 0 0 0-12-2A5 5 0 0 0 7 18Z"/>'}</svg>`;
function decorateControlIcons(){const paths={'←':'M19 12H5m7-7-7 7 7 7','→':'M5 12h14m-7-7 7 7-7 7','↓':'M12 5v14m-7-7 7 7 7-7','↗':'M5 19 19 5M5 5h14v14','‹':'m15 5-7 7 7 7','›':'m9 5 7 7-7 7','×':'m6 6 12 12M6 18 18 6'};document.querySelectorAll('button,a').forEach(control=>{const walker=document.createTreeWalker(control,NodeFilter.SHOW_TEXT),texts=[];while(walker.nextNode())if(/[←→↓↗‹›×]/.test(walker.currentNode.nodeValue)&&!walker.currentNode.parentElement.closest('svg'))texts.push(walker.currentNode);for(const node of texts){const parts=node.nodeValue.split(/([←→↓↗‹›×])/),fragment=document.createDocumentFragment();for(const part of parts){if(paths[part]){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'),path=document.createElementNS('http://www.w3.org/2000/svg','path');for(const [key,value]of Object.entries({class:'ui-icon control-icon',viewBox:'0 0 24 24',width:'16',height:'16',fill:'none',stroke:'currentColor','stroke-width':'1.7','stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':'true',focusable:'false'}))svg.setAttribute(key,value);path.setAttribute('d',paths[part]);svg.append(path);fragment.append(svg)}else fragment.append(document.createTextNode(part))}node.replaceWith(fragment)}})}
const learningTypes = {"Routine":["potty","nap","chew","bite","senior","bedtime","pen","crate","room","alone","quiet","counter","alonehome"],"Foundation":["marker","name","handling","collar","guard","touch"],"Socialization":["sound","people","surfaces","household","watch","car","dogs","lift","office","cowork"],"Enrichment":["find","play","sniffwalk","fetch"],"Skill":["sit","down","mat","recall","drop","release","leave","lead","jump","greet","door","uturn","stay","distraction","teen"],"Care":["stand","teeth","ears","nails","chin","vet","bath","dryer","restrain"]};
function normalizeSkill(s){const valid=Object.keys(learningTypes);return {...s,type:valid.includes(s.type)?s.type:valid.find(type=>learningTypes[type].includes(s.id))||'Skill'}}
const stageNames=['Introduce gently','Build consistency','Try one small change','Comfortable · maintain'];
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, dt=s=>new Date(s+'T12:00:00'), uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
