function bindSkills(){decorateControlIcons();document.querySelectorAll('[data-guide]').forEach(e=>e.onclick=()=>preparationGuide(e.dataset.guide));document.querySelectorAll('[data-skill]').forEach(e=>e.onclick=()=>skillView(e.dataset.skill))}
function editRoutine(){form('Your daily rhythm','<p>Edit the reusable routine: time | task | notes | skill ID. This changes the template for all dates. Keep the four columns on each line.</p><textarea name="lines" rows="18">'+esc((routineForHome()).map(x=>x.join(' | ')).join('\n'))+'</textarea>',async f=>{let rows=f.get('lines').split('\n').filter(x=>x.trim()).map(x=>x.split('|').map(x=>x.trim()));if(rows.some(r=>r.length!==4||!/^([01]\d|2[0-3]):[0-5]\d$/.test(r[0])||(r[3]&&!skills.some(s=>s.id===r[3]))))throw Error('Each line needs HH:MM | task | notes | valid skill ID (or blank).');await put('routine',rows)})}
function editTask(t){form(t?'Edit task':'Add a task',input('time','Time',t?.time||'09:00','time',true)+input('title','Task',t?.title||'','text',true)+input('notes','Specific notes',t?.notes||'')+`<label>Quick guide</label><select name="skill"><option value="">None</option>${skills.map(s=>`<option value="${s.id}" ${s.id===t?.skill?'selected':''}>${s.title}</option>`).join('')}</select>`+(t&&!t.id.startsWith('task:')?'<p>Edits to a template task apply to every day. Use “Add a task” for a one-day change.</p>':'<label><input class="inlinecheck" type="checkbox" name="repeat" '+(t?.repeat?'checked':'')+'> Repeat daily</label>'),async f=>{let v=Object.fromEntries(f);if(t?.careId){throw Error('Use Reschedule on the care task to move its date.')}else if(t?.id.startsWith('prep')){await put('prep-edit:'+t.id,v)}else if(t?.id.startsWith('base')){let rows=structuredClone(routineForHome());rows[Number(t.id.slice(4))]=[v.time,v.title,v.notes,v.skill];await put('routine',rows)}else if(t?.id==='milestone'||t?.id.startsWith('train-')){throw Error('This suggestion is automatic. Add a custom task or edit the daily routine instead.')}else await put(t?.id||'task:'+uid(),{...v,date:day,repeat:f.has('repeat')})})}
function logForm(){form('Learn her rhythm',input('time','Time',new Date().toTimeString().slice(0,5),'time',true)+'<label>Type</label><select name="kind"><option>Pee outside</option><option>Poop outside</option><option>Accident</option><option>Nap started</option><option>Woke up</option><option>Meal</option></select>'+input('note','Notes'),async f=>put('log:'+uid(),{...Object.fromEntries(f),date:day}))}
function reminders(){return list('care:').filter(x=>x.next).sort((a,b)=>a.next.localeCompare(b.next)).slice(0,6).map(x=>`<p><strong>${esc(x.title)}</strong><br><small>${esc(x.next)} · ${esc(x.kind)} ${x.next<today()?'· overdue':''}</small></p>`).join('')||'<p class="muted">Add vet, vaccine, grooming and bath reminders in Profile.</p>'}
function profilePage(){let p=profile(),exp=list('expense:'),month=today().slice(0,7),spent=exp.filter(x=>x.date.startsWith(month)).reduce((a,x)=>a+Number(x.amount),0);$('#app').innerHTML=`<span class="eyebrow">05 / profile</span><h1>${esc(p.name)}</h1><p class="intro">${esc(p.breed)} · Born ${esc(p.birthday)} · Home ${esc(p.home)}</p><div class="grid"><div><section class="card"><span class="eyebrow">home setup</span><h3>Home setup</h3><p><button data-guide="proof">Puppy-proofing & toxins</button> <button data-guide="supplies">Supplies checklist</button></p><p><strong>Nighttime</strong><br>Sleeping in your bed, with safe access and overnight toilet support.</p><p><strong>Working upstairs</strong><br>Supervised freedom in your puppy-proofed bedroom. Start with a manageable area; use a gate when focused work means you cannot watch her.</p><p><strong>Downstairs</strong><br>Meals and relaxed time in her pen, with an open crate available as a voluntary rest spot. Feed the dogs separately.</p><p class="muted">Crate comfort remains useful for travel, grooming or vet care. Closed-door practice is brief and gradual; it is separate from her bed-sharing plan.</p></section><section class="card"><h3>The essentials</h3><p><strong>Food</strong><br>${esc(p.food)}</p><p><strong>Medications & instructions from vet</strong><br>${esc(p.meds)}</p><p><strong>Her big sister</strong><br>${esc(p.sister)}</p><p><strong>Vet</strong> ${esc(p.vet)||'Add contact'}<br><strong>Emergency clinic</strong> ${esc(p.emergency)||'Add contact'}<br><strong>Groomer</strong> ${esc(p.groomer)||'Add contact'}</p><p>${esc(p.notes)}</p><button id="editprofile">Edit profile</button></section><section class="card"><h3>Care & medical records</h3><p class="muted">Record confirmed vaccines and vet-set due dates. Grooming and bath intervals depend on coat, skin and groomer guidance.</p><button id="addcare">+ Add record / reminder</button>${list('care:').sort((a,b)=>(a.next||'9999').localeCompare(b.next||'9999')).map(x=>`<p><span class="tag">${esc(x.kind)}</span> <strong>${esc(x.title)}</strong><br>Last: ${esc(x.date)||'Not recorded'} · Next: ${esc(x.next)||'Not set'}<br>${esc(x.notes)}<br><button data-care="${x.id}">Edit / reschedule</button></p>`).join('')}</section></div><div><section class="card"><h3>The puppy budget</h3><span class="eyebrow">${month} · CAD</span><div class="stats"><div><strong>$${spent.toFixed(2)}</strong>spent</div><div><strong>$${Number(get('budget')||0).toFixed(0)}</strong>monthly plan</div></div><p>${get('budget')?'Remaining: $'+(Number(get('budget'))-spent).toFixed(2):'Set your own monthly allowance.'}</p><button id="budget">Set budget</button> <button id="expense">+ Expense</button>${exp.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<p>${esc(x.date)} · ${esc(x.category)}<br>${esc(x.note)} · $${Number(x.amount).toFixed(2)}</p>`).join('')}</section>${documentsMarkup()}<section class="card"><h3>Coming up</h3>${reminders()}</section><section class="card"><h3>Weight diary</h3><button id="weight">+ Record weight</button>${list('weight:').sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<p>${esc(x.date)} · ${esc(x.kg)} kg</p>`).join('')}</section></div></div>`;bindDocuments();$('#editprofile').onclick=()=>form('Clover’s profile',Object.entries(p).map(([k,v])=>input(k,({home:'Homecoming',birthday:'Birthday',meds:'Medications (vet instructions only)',notes:'Notes / allergies / microchip'}[k]||k),v,['birthday','home'].includes(k)?'date':'text',true)).join(''),async f=>put('profile',Object.fromEntries(f)));function care(id){let x=id?get(id):{};form('Care record',`<label>Type</label><select name="kind">${['Vaccine','Vet','Grooming appointment','Bath','Medication review','Parasite prevention','Other'].map(k=>`<option ${k===x.kind?'selected':''}>${k}</option>`).join('')}</select>`+input('title','Name',x.title||'','text',true)+input('date','Completed date',x.date||'','date')+input('next','Next due / book date',x.next||'','date')+input('time','Schedule time',x.time||'18:00','time')+input('interval','Repeat every N days (optional)',x.interval||'','number')+input('notes','Notes / vet instructions',x.notes||''),async f=>{let v=Object.fromEntries(f);if(v.interval&&(Number(v.interval)<1||!Number.isInteger(Number(v.interval))))throw Error('Repeat interval must be a whole number of days.');await put(id||'care:'+uid(),{...x,...v})})}$('#addcare').onclick=()=>care();document.querySelectorAll('[data-care]').forEach(e=>e.onclick=()=>care(e.dataset.care));$('#budget').onclick=()=>form('Monthly budget (CAD)',input('amount','Amount',get('budget')||'','number',true),async f=>{if(Number(f.get('amount'))<0)throw Error('Use a positive amount.');await put('budget',Number(f.get('amount')))});$('#expense').onclick=()=>form('Add expense',input('date','Date',today(),'date',true)+input('category','Category','Food','text',true)+input('amount','Amount (CAD)','','number',true)+input('note','Notes'),async f=>{if(Number(f.get('amount'))<0)throw Error('Use a positive amount.');await put('expense:'+uid(),Object.fromEntries(f))});$('#weight').onclick=()=>form('Weight diary',input('date','Date',today(),'date',true)+input('kg','Weight (kg)','','number',true),async f=>{if(Number(f.get('kg'))<=0)throw Error('Enter a positive weight.');await put('weight:'+uid(),Object.fromEntries(f))})}
const documentTypes={pdf:'application/pdf',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',txt:'text/plain',csv:'text/csv',rtf:'application/rtf',odt:'application/vnd.oasis.opendocument.text'};
function documentsMarkup(){let docs=list('document:').sort((a,b)=>b.addedAt-a.addedAt);return `<section class="card profile-documents"><h3>Documents</h3><p class="muted">Vet records, insurance, breeder paperwork and more. Up to 40 MB per file.</p><button id="add-document">+ Add documents</button><div class="document-list">${docs.map(d=>`<article class="document-row"><strong>${esc(d.label||d.name)}</strong><small>${esc(d.name)} · ${(d.size/1024/1024).toFixed(1)} MB</small>${d.date?`<small>${esc(d.date)}</small>`:''}${d.note?`<p>${esc(d.note)}</p>`:''}<div class="document-actions">${d.mime==='application/pdf'?`<button data-document-open="${d.id}">Open PDF</button>`:''}<button data-document-download="${d.id}">Download</button><button data-document-edit="${d.id}">Edit</button><button data-document-remove="${d.id}">Remove</button></div></article>`).join('')||'<p class="muted">No documents added yet.</p>'}</div></section>`}
function bindDocuments(){
 $('#add-document').onclick=()=>form('Add documents',`<label for="document-files">PDF, Word, Excel, text, CSV, RTF or OpenDocument</label><input id="document-files" name="files" type="file" accept="${Object.keys(documentTypes).map(x=>'.'+x).join(',')}" multiple required>`+input('label','Label (optional)')+input('date','Document date (optional)','','date')+input('note','Notes (optional)'),async f=>{let files=f.getAll('files').filter(x=>x.size);if(!files.length)throw Error('Choose at least one non-empty document.');for(let file of files){let ext=file.name.split('.').pop().toLowerCase();if(!documentTypes[ext])throw Error('Choose a supported document type.');if(file.size>40*1024*1024)throw Error('Each document must be 40 MB or smaller.')}for(let file of files){let mime=documentTypes[file.name.split('.').pop().toLowerCase()],id=uid();await mediaLocal('put',id,new Blob([file],{type:mime}));await put('document:'+uid(),{name:file.name,file:id,mime,size:file.size,label:f.get('label'),date:f.get('date'),note:f.get('note'),addedAt:Date.now()})}});
 document.querySelectorAll('[data-document-download]').forEach(b=>b.onclick=()=>downloadDocument(b.dataset.documentDownload));
 document.querySelectorAll('[data-document-open]').forEach(b=>b.onclick=()=>openDocument(b.dataset.documentOpen));
 document.querySelectorAll('[data-document-edit]').forEach(b=>b.onclick=()=>{let d=get(b.dataset.documentEdit);form('Document details',input('label','Label (optional)',d.label)+input('date','Document date (optional)',d.date,'date')+input('note','Notes (optional)',d.note),async f=>put(b.dataset.documentEdit,{...d,...Object.fromEntries(f)}))});
 document.querySelectorAll('[data-document-remove]').forEach(b=>b.onclick=()=>removeAttachment(b.dataset.documentRemove,'document'));
}
function removeAttachment(id,kind){let entry=get(id);if(!entry)return;modal(`<h2>Remove ${kind}?</h2><p>${esc(entry.label||entry.title||entry.name||'This memory')} will be removed${kind==='memory'?' from Memories and the home collage':' from Clover’s profile'}.</p><div class="removal-actions"><button id="cancel-removal">Cancel</button><button id="confirm-removal" class="primary">Remove</button></div><p id="removal-error" role="alert"></p>`);$('#cancel-removal').onclick=()=>$('#modal').close();$('#confirm-removal').onclick=async e=>{e.currentTarget.disabled=true;try{if(entry.file)await mediaDelete(entry.file);await put(id,null,true);$('#modal').close();render();toast(kind==='memory'?'Memory removed':'Document removed')}catch(err){$('#removal-error').textContent=err.message;$('#confirm-removal').disabled=false}}}
async function downloadDocument(id){try{let d=get(id),blob=await mediaGet(d.file),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){toast('Could not download document: '+e.message)}}
async function openDocument(id){let d=get(id);modal(`<h2>${esc(d.label||d.name)}</h2><p><button id="download-open-document">Download PDF</button></p><div id="document-preview"></div>`);$('#download-open-document').onclick=()=>downloadDocument(id);let host=$('#document-preview');try{let blob=await mediaGet(d.file);if(!host.isConnected)return;let url=URL.createObjectURL(new Blob([blob],{type:'application/pdf'})),frame=document.createElement('iframe');frame.title=d.label||d.name;frame.src=url;host.append(frame);$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}catch(e){toast('Could not open document: '+e.message)}}
function sources(){$('#app').innerHTML=`<h1>gentle, informed care</h1><section class="card"><p>The routines and short exercises are practical starting templates, not individualized veterinary advice. Adjust meals, toilet frequency, sleep and activity to Clover. Readiness takes priority over age. No automatic medication doses or vaccine dates are prescribed.</p><p><a href="https://avsab.org/resources/position-statements/">AVSAB: humane training & puppy socialization</a></p><p><a href="https://www.akc.org/expert-advice/puppy-information/introducing-puppies-to-senior-dogs/">AKC: introducing puppies to senior dogs</a></p><p><a href="https://vcahospitals.com/pediatric/puppy/behavior-training/when-to-start-puppy-training-classes">VCA: puppy training milestones</a></p><p>Sources reviewed October 31, 2026. App care reminders appear here when opened; there are no background push notifications.</p></section>`}
// IndexedDB keeps media separate from structured records; export includes both.
const mr=indexedDB.open('clover-media',1);mr.onupgradeneeded=()=>mr.result.createObjectStore('files');const mdb=await new Promise((ok,no)=>{mr.onsuccess=()=>ok(mr.result);mr.onerror=no});
const mediaLocal=(method,key,val)=>new Promise((ok,no)=>{let t=mdb.transaction('files',method==='get'?'readonly':'readwrite'),r=t.objectStore('files')[method](...(method==='put'?[val,key]:[key]));r.onsuccess=()=>ok(r.result);r.onerror=no});
async function mediaPut(id,file){await mediaLocal('put',id,file);if(cloud&&user){let {error}=await cloud.storage.from('memories').upload(user.id+'/'+id,file,{contentType:file.type});if(error)throw error}}
async function mediaGet(id){let b=await mediaLocal('get',id);if(b)return b;if(!cloud||!user)throw Error('Sign in to download this attachment.');let {data,error}=await cloud.storage.from('memories').download(user.id+'/'+id);if(error)throw error;await mediaLocal('put',id,data);return data}
async function mediaDelete(id){if(cloud&&user){let{error}=await cloud.storage.from('memories').remove([user.id+'/'+id]);if(error)throw error}await mediaLocal('delete',id)}
let syncing=false;
async function sync(){if(!cloud||!user||syncing)return;syncing=true;try{let dirty=records.filter(x=>x.dirty);for(let x of dirty){if((x.id.startsWith('memory:')||x.id.startsWith('document:'))&&x.value?.file){let file=await mediaLocal('get',x.value.file);if(file){let r=await cloud.storage.from('memories').upload(user.id+'/'+x.value.file,file,{upsert:true,contentType:file.type});if(r.error)throw r.error}}let {error}=await cloud.from('clover_records').upsert({owner:user.id,id:x.id,value:x.value,deleted:x.deleted,updated:x.updated});if(error)throw error;await localPut({...x,dirty:false})}let{data,error}=await cloud.from('clover_records').select('*');if(error)throw error;let current=await all();for(let x of data){let here=current.find(r=>r.id===x.id);if(!here||(!here.dirty&&x.updated>=here.updated))await localPut({id:x.id,value:x.value,deleted:x.deleted,updated:x.updated,dirty:false})}records=await all();$('#account').innerHTML=uiIcon('cloud')+' Synced · connection'}catch(e){toast('Saved on this device. Sync failed: '+e.message);$('#account').innerHTML=uiIcon('cloud')+' Local changes · retry sync'}finally{syncing=false}}
function backendConfig(){if(SUPABASE_CONFIG.url||SUPABASE_CONFIG.key)return {url:SUPABASE_CONFIG.url.trim(),key:SUPABASE_CONFIG.key.trim()};try{let old=JSON.parse(localStorage.getItem('clover-config')||'null');return old?.url&&old?.key?old:null}catch{return null}}
function validateBackendConfig(cfg){if(!cfg?.url||!cfg?.key)throw Error('Website setup is incomplete. Add the project URL and publishable key to config.js once.');let url=new URL(cfg.url);if(url.protocol!=='https:')throw Error('Use your HTTPS Supabase project URL in config.js.');if(cfg.key.startsWith('sb_secret_'))throw Error('Use a publishable key, never a secret key.');if(cfg.key.startsWith('eyJ')){let payload;try{payload=JSON.parse(atob(cfg.key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')))}catch{throw Error('Invalid legacy API key. Use the project publishable key.')}if(payload.role!=='anon')throw Error('Only a publishable key or legacy anon key can be used in this website.')}else if(!cfg.key.startsWith('sb_publishable_'))throw Error('Use the project publishable key in config.js.')}
function downloadSharedConfig(){try{let cfg=backendConfig();validateBackendConfig(cfg);let blob=new Blob(['// Public website configuration. Never add a secret key.\nexport const SUPABASE_CONFIG = '+JSON.stringify({url:cfg.url,key:cfg.key},null,2)+';\n'],{type:'text/javascript'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='config.js';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Replace config.js in your website folder with this file, then upload it.')}catch(e){toast(e.message)}}
async function connect(){if(cloud)return;let cfg=backendConfig();if(!cfg)return;validateBackendConfig(cfg);let{createClient}=await import('https://esm.sh/@supabase/supabase-js@2');cloud=createClient(cfg.url,cfg.key);let{data,error}=await cloud.auth.getSession();if(error)throw error;user=data.session?.user;if(user){let bound=localStorage.getItem('clover-owner');if(bound&&bound!==user.id){await cloud.auth.signOut();user=null;throw Error('This browser is linked to another account. Use a separate browser profile.')}localStorage.setItem('clover-owner',user.id);await sync()}cloud.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT')user=null});}
$('#account').onclick=()=>{let cfg=backendConfig(),configured=!!(cfg?.url&&cfg?.key),legacy=configured&&!SUPABASE_CONFIG.url;modal(`<h2>Connected, wherever you are.</h2><p>${user?'Signed in as '+esc(user.email):'Sign in to access Clover’s saved information across your devices.'}</p><p>Use the same account on your laptop and phone. Sync checks every 30 seconds while open.</p>${!configured?'<p class="notice">One-time website setup: fill in config.js with your Supabase project URL and publishable key, then upload that file with the website. After that, every device needs only your email and password. See SETUP.md.</p>':legacy?'<p class="notice">This browser has your previous project settings. Download the shared configuration and replace config.js in your website folder so your other devices can sign in directly.</p><button id="download-config">Download configured config.js</button>':''}<form id="connection">${input('email','Email',user?.email||'','email',true)}${input('password','Password (minimum 8 characters)','','password',true)}<button name="action" value="login" ${configured?'':'disabled'}>Sign in</button> <button name="action" value="signup" ${configured?'':'disabled'}>Create account</button><p id="authmessage"></p></form><p><button id="sync">Sync now</button> <button id="logout">Sign out</button></p><hr><h3>Keep a backup</h3><p>Export includes records and locally available media. Sync first, and open memories and download profile documents saved on another device before exporting.</p><button id="export">Export backup</button><label>Restore backup (merges by record ID)</label><input id="import" type="file" accept="application/json">`);if($('#download-config'))$('#download-config').onclick=downloadSharedConfig;$('#connection').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{validateBackendConfig(backendConfig());await connect();let args={email:f.get('email'),password:f.get('password')};if(args.password.length<8)throw Error('Use at least 8 characters.');let r=e.submitter.value==='signup'?await cloud.auth.signUp(args):await cloud.auth.signInWithPassword(args);if(r.error)throw r.error;$('#authmessage').textContent=r.data.session?'Signed in. Close to continue.':'Check your email to confirm your account, then sign in.';if(r.data.session){user=r.data.user;let bound=localStorage.getItem('clover-owner');if(bound&&bound!==user.id){await cloud.auth.signOut();user=null;throw Error('Use a separate browser profile for another account.')}localStorage.setItem('clover-owner',user.id);await sync();render()}}catch(e){$('#authmessage').textContent=e.message}};$('#sync').onclick=async()=>{await sync();render()};$('#logout').onclick=async()=>{if(cloud)await cloud.auth.signOut();user=null;$('#account').innerHTML=uiIcon('cloud')+' Local mode';toast('Signed out. Local data remains on this device.');$('#modal').close()};$('#export').onclick=async()=>{let media={};for(let m of [...list('memory:'),...list('document:')])if(m.file){let b=await mediaLocal('get',m.file);if(b)media[m.file]=await new Promise(ok=>{let r=new FileReader();r.onload=()=>ok(r.result);r.readAsDataURL(b)})}let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,records,media})],{type:'application/json'}));a.download='clover-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import').onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());if(v.version!==1||!Array.isArray(v.records))throw Error('Invalid backup');for(let [id,url]of Object.entries(v.media||{})){if(!url.startsWith('data:'))throw Error('Invalid attachment');await mediaLocal('put',id,await fetch(url).then(r=>r.blob()))}for(let x of v.records){if(typeof x.id!=='string'||typeof x.updated!=='number')throw Error('Invalid record');await localPut({...x,updated:Date.now(),dirty:true})}records=await all();await sync();render();toast('Backup restored')}catch(e){toast(e.message)}}};


