function preparationGuide(kind){if(kind==='supplies'){
 modal(`<h2>Puppy supplies</h2><p>Start with the essentials; add more after you learn what Clover likes. These are item recommendations, not a requirement to buy a particular brand.</p>${supplyGroups.map(([title,items])=>`<section class="prep-guide-section"><h3>${title}</h3>${items.map(([id,title,note])=>`<label class="supply-item"><input type="checkbox" data-supply="${id}" ${get('supply:'+id)?'checked':''}><span><strong>${title}</strong><small>${note}</small></span></label>`).join('')}</section>`).join('')}<p>Supervise new toys and chews, choose for her age/size, and remove anything she breaks apart. Feed the dogs separately, including high-value chews.</p><p><a href="https://vcahospitals.com/pediatric/puppy/prep-supplies/new-puppy-checklist" target="_blank" rel="noopener">VCA puppy checklist ↗</a> · <a href="https://vcahospitals.com/pediatric/puppy/prep-supplies/puppy-dental-treats" target="_blank" rel="noopener">VCA chew guidance ↗</a></p>`);
 document.querySelectorAll('[data-supply]').forEach(e=>e.onchange=async()=>{try{await put('supply:'+e.dataset.supply,e.checked)}catch(err){toast(err.message)}});return}
 modal(`<h2>Puppy-proof every room</h2><p>For Clover and her big sister. This covers common hazards, not every poisonous item. Keep unknown plants and products inaccessible until identified.</p><section class="prep-guide-section"><h3>Foods to lock away</h3><ul><li>Chocolate, cocoa and caffeine.</li><li>Grapes, raisins and dried vine currants.</li><li>Xylitol (also labelled birch sugar): check gum, sweets, nut butter and oral-care products.</li><li>Onion, garlic, chives and leeks, including powders.</li><li>Macadamia nuts, alcohol and unbaked yeast dough.</li><li>Mouldy food, compost and rubbish.</li></ul></section><section class="prep-guide-section"><h3>Plants to remove or block access to</h3><ul><li>Sago palm/cycads: highly toxic; all parts must be inaccessible.</li><li>Azalea/rhododendron, oleander, yew, autumn crocus, daffodil and tulip bulbs.</li><li>Pothos, philodendron, dieffenbachia and peace lily: chewing can irritate/burn the mouth.</li><li>Aloe, snake plant, dracaena and English ivy can cause illness.</li></ul><p>Check the exact plant species, fallen leaves, bulbs, soil and garden clippings. A missing plant on this list does not mean it is safe.</p><a href="https://www.aspca.org/pet-care/animal-poison-control/dogs-plant-list" target="_blank" rel="noopener">Search ASPCA’s dog plant database ↗</a></section><section class="prep-guide-section"><h3>Other poisons & household hazards</h3><ul><li>Lock up human/pet medicines, supplements, cannabis/edibles, nicotine and vape liquids.</li><li>Secure detergents, cleaning products, concentrated essential oils, antifreeze, pesticides and rodent bait.</li><li>Block cables, batteries, bins, socks, hair ties, coins and small toys; secure stairs, windows and balconies.</li><li>Bones, corn cobs, fruit pits and swallowed toy parts can obstruct or injure the gut: these are physical hazards, not all poisons.</li><li>Give your older dog a puppy-free feeding/rest area. Keep both dogs away while using household chemicals.</li></ul></section><section class="prep-guide-section"><h3>If exposure is suspected</h3><p>Call your vet or emergency clinic immediately; do not wait for symptoms or induce vomiting unless instructed. Save the package/plant photo, estimated amount and time. ASPCA Poison Control: <a href="tel:18884264435">1-888-426-4435</a> (fees may apply).</p></section><p>References: <a href="https://www.aspca.org/pet-care/aspca-poison-control/people-foods-avoid-feeding-your-pets" target="_blank" rel="noopener">ASPCA foods</a> · <a href="https://vcacanada.com/know-your-pet/toxic-household-hazards-for-dogs" target="_blank" rel="noopener">VCA Canada household hazards</a>. Reviewed October 31, 2026.</p>`)
}
function doneKey(id){return 'done:'+(id.startsWith('prep')?'preparation':day)+':'+id}
function currentTask(ts){if(day!==today()||day<profile().home)return null;let now=new Date().toTimeString().slice(0,5);return ts.filter(t=>t.time<=now).at(-1)?.id||null}
function preparationTasks(){return [
['Book her first vet visit','Ask the breeder for vaccine/deworming records. Confirm pickup timing, feeding and the first checkup.'],
['Prepare bed-sharing & the downstairs pen','Plan safe bed access and prevent falls or gaps. Puppy-proof the bedroom; downstairs, attach an open crate to a pen with water, room to rest and a separate feeding space.'],
['Puppy-proof every room','Secure cables, medications, bins, toxic plants and small swallowable items. Gate stairs and unsafe areas.'],
['Create her sister’s quiet zone','Set up a puppy-free bed and feeding area for your older dog. Arrange gates before Clover arrives.'],
['Collect food & feeding instructions','Get the exact breeder food, measured portions and current meal times. Plan changes with your vet.'],
['Pack the homecoming bag','Secure travel crate/restraint, towel, cleanup supplies, lead, harness, water and breeder contact.'],
['Choose a toilet spot','Decide where to take her immediately after arriving. Have treats and enzymatic cleaner ready.'],
['Find a reward-based puppy class','Ask about vaccine entry requirements, small groups, supervised play and gentle teaching.'],
['Plan the first week of company','Arrange time at home and backup care. Keep visitors and demands low; plan overnight toilet support.'],
['Get ID & emergency details ready','Arrange ID tag, microchip transfer, regular vet and emergency clinic contacts.'],
['Prepare grooming supplies','Soft brush, appropriate comb, puppy-safe shampoo and a non-slip surface. Ask a groomer about coat care.'],
['Agree on family routines','Choose cue words, feeding responsibility, toilet handoffs and a plan for calm dog introductions.'],
['Gather puppy supplies','Use the shopping checklist for home essentials, training treats and puppy-safe toys.']
].map((x,i)=>({id:'prep'+i,time:'',title:x[0],notes:x[1],...get('prep-edit:prep'+i),guide:i===2?'proof':i===12?'supplies':null,skill:['','','','senior','','car','potty','','alone','','handling',''][i]}))}
setInterval(()=>{if(page==='today'&&!$('#modal').open)render()},60000);


const prerequisites={recall:['name'],lead:['collar'],drop:['marker'],greet:['name'],lift:['watch'],office:['mat','car'],cowork:['mat','car','lift'],stay:['release'],leave:['marker'],uturn:['lead'],fetch:['drop'],alonehome:['alone','pen'],distraction:['sit','recall'],teen:['distraction']};
const priority=["potty","nap","chew","bite","senior","bedtime","pen","crate","room","marker","name","handling","collar","alone","guard","sound","people","surfaces","household","watch","find","touch","sit","down","mat","recall","drop","release","stand","lead","jump","teeth","ears","nails","chin","vet","car","restrain","bath","dryer","dogs","greet","door","leave","stay","uturn","quiet","counter","play","sniffwalk","lift","alonehome","fetch","office","cowork","distraction","teen"];
function skillProgress(id){let logs=list('practice:').filter(x=>x.skill===id&&x.date<=day&&x.comfort).sort((a,b)=>a.date.localeCompare(b.date)||(a.at||0)-(b.at||0)),level=0,days=new Set(),last=null;for(let x of logs){last=x;if(x.comfort==='overwhelmed'){level=Math.max(0,level-1);days.clear()}else if(x.comfort==='help'){days.clear()}else if(x.goal){days.add(x.date);if(days.size>=3&&level<3){level++;days.clear()}}}return {level,wins:Math.min(3,days.size),last}}
const cueSkills=new Set(['marker','name','touch','sit','down','recall','drop','release','stand','lead','jump','greet','door','leave','stay','uturn','quiet','counter','fetch','distraction','teen']);
function skillOrder(a,b){return a.week-b.week||priority.indexOf(a.id)-priority.indexOf(b.id)}
function skillReadiness(s){let missing=(prerequisites[s.id]||[]).filter(id=>skillProgress(id).level<1);return s.week>Math.max(8,age()/7)?'For later · suggested introduction '+s.week+'+ weeks':missing.length?'Build first: '+missing.map(id=>skills.find(x=>x.id===id)?.title||id).join(', '):'Ready for a gentle introduction when comfortable'}
function trainingPlan(){
 if(day<profile().home)return [];
 const homeDays=Math.max(0,Math.floor((dt(day)-dt(profile().home))/86400000));
 let ready=skills.filter(s=>s.week<=Math.max(8,age()/7)&&(prerequisites[s.id]||[]).every(id=>skillProgress(id).level>=1));
 let ranked=ready.map(s=>{let p=skillProgress(s.id),gap=p.last?Math.round((dt(day)-dt(p.last.date))/86400000):null;let due=!p.last||(p.last.comfort==='overwhelmed'?gap>=2:p.level===3?gap>=7:gap>=1);let score=!p.last?90-priority.indexOf(s.id)*.6+Math.min(homeDays,30)*.6:p.level===3?40+Math.min(Math.max(gap-7,0),21)*5:80+Math.min(gap,28)*5+(p.last.comfort==='help'?15:0);return {s,p,gap,due,score}}).filter(x=>x.due).sort((a,b)=>b.score-a.score||skillOrder(a.s,b.s));
 // Separate cue learning from home care/social experiences, so neither crowds out the other.
 const exposure=new Set(['sound','people','surfaces','household','watch','dogs']);
 const choose=pool=>{let fresh=pool.filter(x=>!x.p.last).sort((a,b)=>priority.indexOf(a.s.id)-priority.indexOf(b.s.id));return homeDays%3===0&&fresh.length?fresh[0]:pool[0]};
 const cue=choose(ranked.filter(x=>cueSkills.has(x.s.id))),lifePool=ranked.filter(x=>!cueSkills.has(x.s.id)),preferred=lifePool.filter(x=>exposure.has(x.s.id)===(homeDays%2===1)),life=choose(preferred.length?preferred:lifePool);
 return [cue,life].filter(Boolean).map(({s,p})=>({...s,title:s.title+' · '+stageNames[p.level].toLowerCase(),reason:(cueSkills.has(s.id)?'Cue practice: ':'Everyday-life practice: ')+(p.last?.comfort==='overwhelmed'?'After a pause, offer a much easier version only if relaxed; skip if still worried.':p.last?.comfort==='help'?'Repeat with help in a familiar place; do not add difficulty.':p.level===3?'An easy maintenance check; keep rewarding.':p.level>0?stageNames[p.level]+': '+p.wins+'/3 comfortable success days. '+s.goal:'Introduce one tiny step. '+s.goal)}));
}

function behaviourGuide(returnSkill){modal(`<span class="eyebrow">kind, clear boundaries</span><h2>Help her choose something better.</h2><p>You can stop access to an unwanted behaviour without shouting, frightening or hurting her. She still needs clear limits and help learning what to do.</p><ol><li><strong>Prevent it.</strong> Move shoes, clear counters, use a gate or supervise closely. Make the unwanted option harder to reach before it happens.</li><li><strong>Interrupt calmly and safely.</strong> Pause play, step away or guide her away with a familiar cue such as “touch” or “this way”. Avoid chasing, grabbing her muzzle or jerking the lead.</li><li><strong>Offer a useful alternative.</strong> Give her a chew, invite four paws on the floor, or guide her to a mat. Make the alternative easy enough to succeed.</li><li><strong>Reward that alternative.</strong> Mark and reward the moment she does it. Also catch the good behaviour before trouble starts, so she does not have to misbehave to get your attention.</li><li><strong>Change the setup.</strong> Repeated trouble often means too much freedom, too much excitement, an unmet toilet/sleep need, or a task that is too hard. Adjust the environment and practice later at an easier level.</li></ol><div class="boundary-examples"><h3>In the moment</h3><dl><dt>Teeth on hands</dt><dd>Pause play and offer a suitable toy. If she keeps biting, step behind a gate briefly for a calm reset; check whether she needs sleep or a toilet trip.</dd><dt>Chewing a shoe</dt><dd>Trade for a treat or suitable toy, then put shoes away. Reward choosing her own chew next time.</dd><dt>Jumping up</dt><dd>Pause attention while she jumps. Offer attention and rewards when her paws return to the floor; use a gate for exciting arrivals.</dd><dt>Pestering her sister</dt><dd>Redirect Clover and separate with a gate before tension builds. Protect your older dog’s quiet space and never make her tolerate pestering.</dd><dt>Barking or growling</dt><dd>Check what is causing it. Add distance or remove the trigger; don’t punish warning signals. Fear, pain or guarding needs a different plan from attention-seeking.</dd><dt>A dangerous object</dt><dd>Keep her safe first; trade if safe to do so and avoid chasing or forcing her mouth open. Suspected swallowing, poison exposure, pain or injury warrants prompt veterinary advice.</dd></dl></div><p class="muted">Don’t ignore fear, pain, distress or unsafe behaviour. For repeated guarding, aggression or separation distress, speak with your vet and a qualified reward-based behaviour professional.</p><p><a href="https://avsab.org/what-are-reward-based-training-methods-for-dogs-and-cats/" target="_blank" rel="noopener">AVSAB: reward-based training & humane management ↗</a></p>${returnSkill?'<button id="backskill">← Back to practice</button>':''}`);if(returnSkill)$('#backskill').onclick=()=>skillView(returnSkill)}
async function memoryView(m,sequence){
 if(!m.file){editMemory(m.id);return}
 let items=(sequence||list('memory:').sort((a,b)=>albumDate(b).localeCompare(albumDate(a))||(b.addedAt||0)-(a.addedAt||0))).filter(x=>x.file),index=items.findIndex(x=>x.id===m.id);
 const heading=[m.title?`<span class="viewer-title">${esc(m.title)}</span>`:'',m.date?`<time datetime="${esc(m.date)}">${dt(m.date).toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'})}</time>`:''].join('');
 modal(`<div class="media-viewer"><div class="viewer-media"></div>${heading?`<div class="viewer-caption">${heading}</div>`:''}${items.length>1?`<button class="viewer-arrow viewer-prev" aria-label="Previous memory" ${index<=0?'disabled':''}>‹</button><button class="viewer-arrow viewer-next" aria-label="Next memory" ${index>=items.length-1?'disabled':''}>›</button>`:''}</div>`);
 const host=$('.viewer-media'),dialog=$('#modal');let objectUrl=null;
 const release=()=>{host.querySelector('video')?.pause();if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}};
 viewerCleanup=release;dialog.addEventListener('close',release,{once:true});
 const move=offset=>{let next=items[index+offset];if(next)memoryView(next,items)};
 if($('.viewer-prev'))$('.viewer-prev').onclick=()=>move(-1);
 if($('.viewer-next'))$('.viewer-next').onclick=()=>move(1);
 dialog.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){if(e.target?.tagName==='VIDEO')return;e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}};
 try{let blob=await mediaGet(m.file);if(!host.isConnected)return;objectUrl=URL.createObjectURL(blob);let el=document.createElement(blob.type.startsWith('video')?'video':'img');el.src=objectUrl;el.alt=memoryLabel(m);if(el.tagName==='VIDEO'){el.controls=true;el.playsInline=true}host.append(el)}catch(e){toast('Could not open memory: '+e.message)}
}
function displayTime(time){if(!time)return '';let[h,m]=time.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')}${h<12?'am':'pm'}`}
function weekStrip(){let selected=dt(day);return Array.from({length:7},(_,i)=>{let d=new Date(selected);d.setDate(d.getDate()+i-3);let key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return `<button data-day="${key}" class="${key===day?'selected':''} ${key===today()?'is-today':''}" aria-label="${d.toLocaleDateString('en-CA',{weekday:'long',month:'long',day:'numeric'})}" aria-pressed="${key===day}"><span>${d.toLocaleDateString('en-CA',{weekday:'short'})}</span><strong>${d.getDate()}</strong>${key===today()?'<i></i>':''}</button>`}).join('')}
function dayRail(ts,done){let until=Math.round((dt(profile().home)-dt(day))/86400000),focus=day>=profile().home?trainingPlan()[0]:null;return `<div class="rail-sticker"><img src="clover-logo.png" alt="Clover logo"></div><section class="rail-note"><span class="eyebrow">${until>0?'HOME / '+profile().home:'CHECKLIST'}</span><div class="rail-number">${until>0?until:done}<small>${until>0?'days to go':'of '+ts.length+' done'}</small></div></section>${focus?`<section class="rail-focus"><span class="eyebrow">TRAINING FOCUS</span><h3>${focus.title.split(' · ')[0]}</h3><p>${focus.reason}</p><button data-skill="${focus.id}">View practice ↗</button></section>`:'<section class="rail-focus"><span class="eyebrow">SETUP / 3 SPACES</span><h3>Bedroom.<br>Downstairs.<br>Bedtime.</h3><p>Supervised room access. Downstairs pen with an open crate. Sleeping in your bed.</p></section>'}`}
function calendarDates(){let d=dt(day),start=new Date(d);start.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>{let x=new Date(start);x.setDate(start.getDate()+i);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`})}
function tasksOn(date){let previous=day;try{day=date;return tasks()}finally{day=previous}}
function currentTaskOn(date,items){let previous=day;try{day=date;return currentTask(items)}finally{day=previous}}
function taskType(t){if(t.id.startsWith('train-'))return 'training';if(/food|breakfast|lunch|dinner/i.test(t.title))return 'meal';if(/rest|bedtime|settle|pen time/i.test(t.title))return 'rest';if(t.skill)return 'practice';return 'care'}
function weekCalendar(){let dates=calendarDates(),before=dates.every(x=>x<profile().home);return `<div class="calendar-caption"><span>${before?'PREPARATION / choose a day to view its checklist':'WEEK PLAN / click a block for notes & practice'}</span><span>${dt(dates[0]).toLocaleDateString('en-CA',{month:'short',day:'numeric'})} — ${dt(dates[6]).toLocaleDateString('en-CA',{month:'short',day:'numeric'})}</span></div><div class="calendar-scroll"><div class="calendar-board ${before?'prep-board':''}"><div class="calendar-head"><span></span>${dates.map(date=>`<button data-day="${date}" class="${date===day?'selected':''}"><span>${dt(date).toLocaleDateString('en-CA',{weekday:'short'})}</span><strong>${dt(date).getDate()}</strong></button>`).join('')}</div><div class="calendar-body"><div class="time-axis">${before?'<span>PREP</span>':Array.from({length:16},(_,i)=>`<span style="top:${i*80}px">${String(i+7).padStart(2,'0')}:00</span>`).join('')}</div>${dates.map(date=>{let tasks=tasksOn(date);if(date<profile().home)return `<div class="calendar-column prep-column"><p class="prep-shared">${tasks.length} shared prep items.<br>Not timed appointments.</p>${tasks.slice(0,3).map(t=>`<button class="prep-event" data-eventdate="${date}" data-event="${t.id}">${esc(t.title)}</button>`).join('')}<button class="prep-open" data-prepday="${date}">Open checklist ↗</button></div>`;let prevEnd=-1,lane=0;return `<div class="calendar-column">${tasks.filter(t=>t.time).map(t=>{let [h,m]=t.time.split(':').map(Number),mins=h*60+m;if(mins<420||mins>1380)return '';lane=mins<prevEnd?1-lane:0;let overlap=tasks.some(o=>o.id!==t.id&&o.time&&Math.abs((Number(o.time.slice(0,2))*60+Number(o.time.slice(3)))-mins)<35);prevEnd=mins+35;return `<button class="calendar-event type-${taskType(t)} ${date===today()&&currentTaskOn(date,tasks)===t.id?'current':''}" style="top:${(mins-420)*80/60}px;left:${overlap?lane*50:0}%;width:${overlap?'49':'98'}%" data-eventdate="${date}" data-event="${t.id}" title="${esc(t.time+' '+t.title+' — '+t.notes)}"><time>${displayTime(t.time)}</time><span>${esc(t.title.split(' · ')[0])}</span></button>`}).join('')}</div>`}).join('')}</div></div></div><div class="calendar-legend"><span class="type-meal">Meals</span><span class="type-rest">Rest / settling</span><span class="type-training">Training</span><span class="type-practice">Care / practice</span></div><p class="calendar-footnote">Blocks mark start times; their height does not prescribe duration. Toilet breaks remain flexible. Future training uses the progress currently recorded.</p>`}
function calendarDetail(date,id){let t=tasksOn(date).find(x=>x.id===id);if(!t)return;modal(`<span class="eyebrow">${esc(date)} ${esc(t.time)}</span><h2>${esc(t.title)}</h2><p>${esc(t.notes)}</p><p><button id="calendar-open-day">Open this day ↗</button>${t.skill?' <button id="calendar-skill" class="primary">Practice guide ↗</button>':''}${t.careId?' <button id="calendar-care">Reschedule</button> <button id="calendar-care-done">Complete</button>':''}</p>`);$('#calendar-open-day').onclick=()=>{day=date;scheduleView='day';localStorage.setItem('clover-schedule-view-v2','day');$('#modal').close();render()};if(t.careId){$('#calendar-care').onclick=()=>postponeCare(t.careId);$('#calendar-care-done').onclick=()=>completeCare(t.careId)}if(t.skill)$('#calendar-skill').onclick=()=>{day=date;skillView(t.skill)}}


function landingMarkup(){return `<section class="landing" aria-label="Clover photo collage"><div class="landing-stack" id="landing-stack"></div><div class="landing-controls"><button id="add-landing-photos">+ Add photos</button><button id="manage-landing">Manage photos</button><a href="#daily-schedule" id="to-schedule">Daily schedule ↓</a></div></section>`}
async function hydrateLanding(){landingUrls.forEach(u=>URL.revokeObjectURL(u));landingUrls=[];let host=$('#landing-stack');if(!host)return;let items=list('memory:').filter(m=>m.file&&m.featured!==false&&(!m.mime||m.mime.startsWith('image/'))).sort((a,b)=>(b.addedAt||0)-(a.addedAt||0)).slice(0,18),photos=[];host.setAttribute('aria-busy','true');for(let m of items){try{let b=await mediaGet(m.file);if(b.type.startsWith('image/'))photos.push({m,b})}catch(e){toast('Some collage photos could not load. Check your connection.')}}if(!host.isConnected)return;host.removeAttribute('aria-busy');if(!photos.length){host.classList.add('is-empty');host.innerHTML='<div class="empty-photo-outline outline-one"></div><div class="empty-photo-outline outline-two"></div><div class="landing-empty-copy"><h1>clover</h1><p>Add your photos to start the collage.</p></div>';return}host.classList.remove('is-empty');let positions=[[2,11,-8],[19,18,6],[38,7,-5],[57,16,7],[76,10,-3],[7,40,3],[27,37,-7],[48,42,4],[69,39,-6],[1,66,-3],[21,63,7],[42,68,-4],[63,64,6],[78,65,-5],[12,25,-6],[34,28,5],[54,27,-4],[73,28,6]];photos.forEach(({m,b},i)=>{let [x,y,r]=positions[i],button=document.createElement('button'),img=document.createElement('img');button.className='stack-photo';button.style.cssText=`--photo-x:${x}%;--photo-y:${y}%;--photo-angle:${r}deg;--photo-z:${i+1}`;button.setAttribute('aria-label','Open '+memoryLabel(m));button.title=memoryLabel(m);let url=URL.createObjectURL(b);landingUrls.push(url);img.src=url;img.alt=memoryLabel(m);img.draggable=false;button.append(img);button.onclick=()=>memoryView(m);host.append(button)})}
function addedLabel(m){return m.addedAt?'Added '+new Date(m.addedAt).toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric'}):'Added date unavailable · older entry'}
function addMemoryForm(home){form(home?'Add photos':'Add memory',input('date','Memory date (optional)','','date')+input('title','Title (optional)')+input('note','Notes')+`<label for="memory-file">${home?'Photos':'Photos or videos'} · up to 40 MB each</label><input id="memory-file" type="file" name="file" accept="${home?'image/*':'image/*,video/*'}" multiple ${home?'required':''}><label><input class="inlinecheck" type="checkbox" name="featured" checked> Show photos on the home collage</label><p class="muted">Choose Photo Library on your phone. Videos stay in Memories. One entry is created per file.</p>`,async f=>{let files=f.getAll('file').filter(x=>x.size);if(home&&!files.length)throw Error('Choose at least one photo.');if(files.some(x=>x.size>40*1024*1024))throw Error('Choose files under 40 MB each.');if(home&&files.some(x=>x.type&&!x.type.startsWith('image/')))throw Error('Choose photos for the collage.');if(!files.length&&!String(f.get('note')||'').trim()&&!String(f.get('title')||'').trim())throw Error('Add a photo, video or note.');if(!files.length)files=[null];for(let file of files){let path=null;if(file){path=uid();await mediaPut(path,file)}await put('memory:'+uid(),{date:f.get('date'),title:f.get('title'),note:f.get('note'),file:path,mime:file?.type||'',addedAt:Date.now(),featured:f.has('featured')})}})}
function editMemory(id){let m=get(id);form('Edit memory',input('date','Memory date (optional)',m.date||'','date')+input('title','Title (optional)',m.title||'')+input('note','Notes',m.note)+`<label><input class="inlinecheck" type="checkbox" name="featured" ${m.featured!==false?'checked':''}> Show photo on the home collage</label><p class="muted">${addedLabel(m)}. Unchecking this keeps the photo in Memories.</p>`,async f=>put(id,{...m,date:f.get('date'),title:f.get('title'),note:f.get('note'),featured:f.has('featured')}))}

function careTasks(){let due=list('care:').filter(x=>x.next&&(x.next===day||(day===today()&&x.next<day))).map(x=>({id:x.id,careId:x.id,time:x.time||'18:00',title:x.title,notes:`${x.kind} · ${x.next<day?'Overdue from '+x.next+'. ':''}${x.notes||''}`,skill:''}));let completed=list('carelog:').filter(x=>x.date===day).map(x=>({...x,time:x.time||'18:00',notes:'Completed · '+(x.notes||''),skill:'',completed:true}));return [...due,...completed]}
function postponeCare(id){let x=get(id);form('Reschedule '+esc(x.title),input('next','New date',x.next||day,'date',true)+input('time','Time',x.time||'18:00','time',true)+input('reason','Note (optional)'),async f=>put(id,{...x,next:f.get('next'),time:f.get('time'),moves:[...(x.moves||[]),{from:x.next,to:f.get('next'),at:Date.now(),note:f.get('reason')}]}))}
function completeCare(id){let x=get(id),next='';if(Number(x.interval)>0){let d=dt(day);d.setDate(d.getDate()+Number(x.interval));next=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}form('Complete '+esc(x.title),input('date','Completed date',day,'date',true)+input('next','Next due date (optional)',next,'date')+input('notes','Completion notes',x.notes||''),async f=>{await put('carelog:'+uid(),{careRecord:id,title:x.title,date:f.get('date'),time:x.time||'18:00',notes:f.get('notes')});await put(id,{...x,date:f.get('date'),next:f.get('next')});toast('Care recorded. The next date is on your schedule.')})}
function scheduleCare(){form('Schedule care',`<label>Type</label><select name="kind"><option>Bath</option><option>Grooming appointment</option><option>Vet</option><option>Vaccine</option><option>Medication review</option><option>Parasite prevention</option><option>Other</option></select>`+input('title','Task name','','text',true)+input('next','Date',day,'date',true)+input('time','Time','18:00','time',true)+input('interval','Repeat every N days (optional)','','number')+input('notes','Notes / instructions')+'<p class="muted">Choose bathing and grooming timing with your groomer or vet. Use their confirmed dates for vaccines and medications.</p>',async f=>{let v=Object.fromEntries(f);if(v.interval&&(Number(v.interval)<1||!Number.isInteger(Number(v.interval))))throw Error('Use a whole number of days.');await put('care:'+uid(),v)})}

function memoryLabel(m){return m.title?.trim()||'Memory'}
function albumDate(m){return m.date|| (m.addedAt?new Date(m.addedAt).getFullYear()+'-'+String(new Date(m.addedAt).getMonth()+1).padStart(2,'0')+'-'+String(new Date(m.addedAt).getDate()).padStart(2,'0'):'')}
function albumMonth(m){return albumDate(m).slice(0,7)||'undated'}
function renderAlbum(){
 const app=$('#app');app.innerHTML=`<h1>memories</h1><div class="toolbar album-toolbar"><button id="memory" class="primary">+ Add memory</button><input id="memorydate" type="date" aria-label="Filter memory date"><button id="clearfilter">Show all</button></div><div id="album" class="album"></div>`;
 const paint=async()=>{
 const target=$('#album'),filter=$('#memorydate').value;
 let items=list('memory:').filter(m=>!filter||albumDate(m)===filter).sort((a,b)=>albumDate(b).localeCompare(albumDate(a))||(b.addedAt||0)-(a.addedAt||0)),groups=new Map();
 for(let m of items){let key=albumDate(m)||'undated';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m)}
 target.innerHTML=items.length?[...groups].map(([key,entries])=>`<section class="photo-date-group"><div class="photo-date-heading"><h2>${key==='undated'?'Undated':dt(key).toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'})}</h2><small>${entries.length} ${entries.length===1?'memory':'memories'}</small></div><div class="photo-grid">${entries.map(m=>`<div class="photo-cell"><button class="photo-tile" data-open-memory="${m.id}" aria-label="Open ${esc(memoryLabel(m))}">${m.file?'':`<span class="note-thumbnail">${esc(m.note||m.title||'Memory')}</span>`}</button><details class="memory-menu"><summary aria-label="Actions for ${esc(memoryLabel(m))}">•••</summary><div><button data-edit-memory="${m.id}">Edit</button><button data-remove-memory="${m.id}">Remove</button></div></details></div>`).join('')}</div></section>`).join(''):'<p class="album-empty">Add photos, videos or notes to start your album.</p>';
 target.querySelectorAll('[data-edit-memory]').forEach(button=>button.onclick=()=>editMemory(button.dataset.editMemory));
 target.querySelectorAll('[data-remove-memory]').forEach(button=>button.onclick=()=>removeAttachment(button.dataset.removeMemory,'memory'));
 target.querySelectorAll('[data-open-memory]').forEach(button=>button.onclick=()=>memoryView(items.find(m=>m.id===button.dataset.openMemory),items));
 for(let m of items){if(!m.file)continue;try{let blob=await mediaGet(m.file);if(!target.isConnected)return;let tile=[...target.querySelectorAll('[data-open-memory]')].find(e=>e.dataset.openMemory===m.id);if(!tile)continue;let url=URL.createObjectURL(blob),video=blob.type.startsWith('video'),el=document.createElement(video?'video':'img');el.alt=memoryLabel(m);el.src=url;if(video){el.muted=true;el.playsInline=true;el.preload='metadata';let badge=document.createElement('span');badge.className='video-badge';badge.textContent='Video';tile.append(badge);el.onloadedmetadata=()=>{if(Number.isFinite(el.duration))badge.textContent=Math.floor(el.duration/60)+':'+String(Math.floor(el.duration%60)).padStart(2,'0')};window.addEventListener('hashchange',()=>URL.revokeObjectURL(url),{once:true})}else{el.loading='lazy';el.onload=()=>URL.revokeObjectURL(url)}tile.prepend(el)}catch(e){toast('Could not load memory: '+e.message)}}
 };$('#memory').onclick=()=>addMemoryForm(false);$('#memorydate').onchange=paint;$('#clearfilter').onclick=()=>{$('#memorydate').value='';paint()};paint()
}
window.addEventListener('hashchange',render);window.addEventListener('focus',async()=>{await sync();render()});setInterval(async()=>{await sync()},30000);render();try{await connect();render()}catch(e){toast('Local mode: '+e.message)}document.querySelector('#loading')?.remove();
